import { useEffect, useState } from 'react';
import { getProfile } from '../api/auth';
import axios from '../api/axios';

export default function HomePage() {
  const [user, setUser] = useState(null);
  const [loading, setLoading] = useState(true);
  const [procedures, setProcedures] = useState([]);
  const [appointments, setAppointments] = useState([]);
  useEffect(() => {
  getProfile()
    .then(res => {
      setUser(res.data);

      // грузим только будущие записи клиента
      axios.get('/appointments/me')
        .then(r => setAppointments(r.data))
        .catch(err => console.error('Ошибка загрузки записей:', err));
    })
    .catch(() => setUser(null))
    .finally(() => setLoading(false));

  axios.get('/procedures')
    .then(res => setProcedures(res.data))
    .catch(err => console.error('Ошибка загрузки процедур:', err));
}, []);

  return (
    <main className="container section fade-in">
      <h1 className="h1">Добро пожаловать!</h1>
      <div className="grid">
        {/* профиль */}
        <article className="card card--half">
          <h2 className="h2">Профиль</h2>
          {loading ? (
            <p className="muted">Загрузка...</p>
          ) : !user ? (
            <p className="muted">Войдите или зарегистрируйтесь</p>
          ) : (
            <div className="info-list">
              <div className="info-list__item">
                <span className="info-list__label">ФИО</span>
                <span>{user.fullName}</span>
              </div>
              <div className="info-list__item">
                <span className="info-list__label">Email</span>
                <span>{user.email}</span>
              </div>
              <div className="info-list__item">
                <span className="info-list__label">Роль</span>
                <span>{user.role}</span>
              </div>
            </div>
          )}
        </article>

        {/* действия */}
        <article className="card card--half">
          <h2 className="h2">Действия</h2>
          <div className="form__actions">
            <a className="btn" href="/appointments">Записаться</a>
            <a className="btn btn--ghost" href="/procedures">Процедуры</a>
          </div>
        </article>

        {/* процедуры */}
        <article className="card card--full">
          <h2 className="h2">Доступные процедуры</h2>
          {procedures.length === 0 ? (
            <p className="muted">Нет доступных процедур</p>
          ) : (
            <ul className="info-list">
              {procedures.map(p => (
                <li key={p._id} className="info-list__item">
                  <span className="info-list__label">{p.name}</span>
                  <span>{p.price} ₽ / {p.durationMin} мин</span>
                </li>
              ))}
            </ul>
          )}
        </article>



      </div>
    </main>
  );
}
